import numpy as np, bpy, math, itertools

def load_srgb(path):
    im = bpy.data.images.load(path); W,H = im.size
    px = np.array(im.pixels[:], dtype=np.float32).reshape(H,W,4)[...,:3]
    srgb = np.where(px<=0.0031308, px*12.92, 1.055*np.power(np.clip(px,0,None),1/2.4)-0.055)
    return np.flipud(srgb)

cams = [
    (np.array([-7.1614,-9.7382,4.5476]), np.array([0.5663,0.7722,-0.2883]), np.array([0.1705,0.2325,0.9575])),
    (np.array([10.7683,-6.3052,4.4989]), np.array([-0.8129,0.5081,-0.2845]), np.array([-0.2413,0.1508,0.9587])),
    (np.array([-7.5517,9.9896,4.6759]), np.array([0.5963,-0.7454,-0.2981]), np.array([0.1862,-0.2328,0.9545])),
]
fov = math.radians(39.6); W=H=768
camdata=[]
for pos,look,up in cams:
    f = look/np.linalg.norm(look)
    r = np.cross(f,up); r/=np.linalg.norm(r)
    u = np.cross(r,f)
    camdata.append((pos,r,u,f))

def pixel_ray(px,py,i):
    pos,r,u,f = camdata[i]
    nx = (px+0.5 - W/2)/(W/2)*math.tan(fov/2)
    ny = (H/2 - py-0.5)/(H/2)*math.tan(fov/2)
    d = f + nx*r + ny*u
    return d/np.linalg.norm(d)

def triangulate(pts):  # pts: list of (cam_i, px, py)
    sols=[]
    for (i,ax,ay),(j,bx,by) in itertools.combinations(pts,2):
        p1 = camdata[i][0]; d1 = pixel_ray(ax,ay,i)
        p2 = camdata[j][0]; d2 = pixel_ray(bx,by,j)
        w = p1-p2
        a = d1@d1; b=d1@d2; c=d2@d2; d=d1@w; e=d2@w
        den = a*c-b*b
        if abs(den)<1e-9: continue
        s = (b*e-c*d)/den; t=(a*e-b*d)/den
        pa = p1+s*d1; pb = p2+t*d2
        sols.append((pa+pb)/2)
    return np.mean(sols,axis=0) if sols else None

# per-view spatial crops: name -> list of (view, (x0,x1,y0,y1), colorcond)
def get_mask(img, cond, crop=None):
    R,G,B = img[...,0],img[...,1],img[...,2]
    mx = img.max(-1); mn = img.min(-1)
    neutral = (mx-mn) < 0.05
    if cond=='chair': m = (R > G+0.08)
    elif cond=='sofa': m = (B-R>0.03)&(mx>=0.5)
    elif cond=='cabinet': m = neutral&(mx>0.88)&(mx<0.985)
    elif cond=='tv': m = neutral&(mx>0.69)&(mx<0.79)
    elif cond=='band': m = neutral&(mx>0.50)&(mx<0.69)
    elif cond=='desk': m = neutral&(mx>=0.60)&(mx<0.87)
    if crop:
        x0,x1,y0,y1 = crop
        cm = np.zeros_like(m); cm[y0:y1, x0:x1]=True
        m &= cm
    return m

