}
results={}
for name,(cond,crops) in specs.items():
    centers=[]; info=[]
    for (i,crop) in crops:
        img = load_srgb(f"/app/input/render_000{i}.png")
        m = get_mask(img,cond,crop)
        ys,xs = np.nonzero(m)
        if len(xs)<200:
            info.append(f"view{i}: FEW {len(xs)}"); continue
        centers.append((i, xs.mean(), ys.mean()))
        info.append(f"view{i}: n={len(xs)} bbox x[{xs.min()},{xs.max()}] y[{ys.min()},{ys.max()}] c=({xs.mean():.0f},{ys.mean():.0f})")
    p = triangulate(centers)
    results[name]=p
